const D = { density:.6, energy:.62, speed:1, scale:1, curl:.5, sway:.55, hue:275, x:.5, y:.92, style:'delta', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const u = Math.min(width, height);
const clp = (v,a,b)=>Math.max(a,Math.min(b,v));
const wh = h => ((h%360)+360)%360;
const st = P.style;
const sec = K.section|0;
const intn = (K.intensity!=null?K.intensity:.6);
const aA = clp(P.alpha,0,100)/100;

// ---- style config: distinct rendering philosophies ----
// topB/botB = ground gradient (HSB) top->bottom(root) ; rootGlow = bloom at delta mouth
// stops = 3-stop orbit-length hue ramp (young->mid->old) ; add = additive glow vs flat ink
let cfg;
if (st==='coral')       cfg={topB:[196,72,9],  botB:[318,58,17], rootGlow:[330,72,40], stops:[338,302,176], sat:84, add:true,  coreBri:92, glowA:15, coreA:30, glintH:326, blur:true};
else if (st==='autumn') cfg={topB:[14,72,9],   botB:[34,82,18],  rootGlow:[42,92,44],  stops:[6,30,50],     sat:90, add:true,  coreBri:96, glowA:16, coreA:32, glintH:44,  blur:true};
else if (st==='bio')    cfg={topB:[222,82,7],  botB:[196,82,15], rootGlow:[168,92,40],  stops:[172,150,286], sat:92, add:true,  coreBri:99, glowA:18, coreA:30, glintH:172, blur:true};
else if (st==='ink')    cfg={topB:[38,9,90],   botB:[36,12,80],  rootGlow:[34,14,72],  stops:[32,30,28],    sat:14, add:false, coreBri:15, glowA:9,  coreA:44, glintH:30,  blur:false};
else /* delta */        cfg={topB:[238,70,15], botB:[276,48,30], rootGlow:[44,66,60],  stops:[283,188,46],  sat:88, add:true,  coreBri:96, glowA:16, coreA:32, glintH:48,  blur:true};

const rootX = clp(P.x,0.05,0.95)*width, rootY = clp(P.y,0.05,0.99)*height;

// ---- HSB->RGB for the ground buffer ----
function h2r(h,s,b){ h=wh(h); s=clp(s,0,100)/100; b=clp(b,0,100)/100; const c=b*s, x=c*(1-Math.abs((h/60)%2-1)), m=b-c; let r,g,bl;
  if(h<60){r=c;g=x;bl=0;} else if(h<120){r=x;g=c;bl=0;} else if(h<180){r=0;g=c;bl=x;}
  else if(h<240){r=0;g=x;bl=c;} else if(h<300){r=x;g=0;bl=c;} else {r=c;g=0;bl=x;}
  return [(r+m)*255,(g+m)*255,(bl+m)*255]; }

// ---- cached ground gradient (rebuild on size / style / hue / section) ----
const gKey = width+'x'+height+':'+st+':'+(P.seed|0)+':'+Math.round(P.hue)+':'+sec;
if (!S.gb || S.gKey !== gKey){
  const BW=Math.max(360, Math.min(640, Math.round(width/2.4))), BH=Math.max(48, Math.round(BW*height/width));
  if (!S.gb || S.gbw!==BW || S.gbh!==BH){ if(S.gb) S.gb.remove(); S.gb=createGraphics(BW,BH); S.gb.pixelDensity(1); S.gbw=BW; S.gbh=BH; }
  const gb=S.gb; gb.loadPixels(); const px=gb.pixels; const asp=(BW/BH);
  const rfx=clp(P.x,0.05,0.95), rfy=clp(P.y,0.05,0.99);
  const hd=(P.hue-275)*0.5, sd=sec*7;
  for (let j=0;j<BH;j++){
    const vy=j/(BH-1);
    for (let i=0;i<BW;i++){
      const fx=i/(BW-1);
      const dx=(fx-rfx)*asp, dy=(vy-rfy);
      const dist=Math.sqrt(dx*dx+dy*dy);
      let bloom=clp(1-dist*1.15,0,1); bloom=bloom*bloom;
      const hh = wh(cfg.topB[0]+(cfg.botB[0]-cfg.topB[0])*vy + hd + sd);
      const ss = cfg.topB[1]+(cfg.botB[1]-cfg.topB[1])*vy;
      let bb = cfg.topB[2]+(cfg.botB[2]-cfg.topB[2])*vy;
      const gh = wh(cfg.rootGlow[0]+hd+sd);
      const c1=h2r(hh,ss,bb), c2=h2r(gh,cfg.rootGlow[1],cfg.rootGlow[2]);
      const o=4*(j*BW+i);
      px[o]   = clp(c1[0]*(1-bloom)+c2[0]*bloom,0,255);
      px[o+1] = clp(c1[1]*(1-bloom)+c2[1]*bloom,0,255);
      px[o+2] = clp(c1[2]*(1-bloom)+c2[2]*bloom,0,255);
      px[o+3] = 255;
    }
  }
  gb.updatePixels(); S.gKey=gKey;
}

// ---- seed-deterministic Collatz strand geometry (rebuild on seed change) ----
const NMAX=220, CAP=64;
if (S.seedUsed!==P.seed || !S.str){
  S.seedUsed=P.seed;
  const fr=i=>{ const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453; return s-Math.floor(s); };
  const str=[]; const seedInt=(P.seed|0);
  for (let gi=0;gi<NMAX;gi++){
    const n = 3 + (Math.floor(fr(gi+1)*9000) + gi*7 + seedInt*13);
    let v=n%100000, guard=0; if(v<3)v+=3;
    const par=[];
    while (v>1 && guard++<400){ par.push(v%2===0?0:1); v=(v%2===0)?v/2:3*v+1; }
    const L=par.length;
    const cap=Math.min(L,CAP);
    const p8=new Uint8Array(cap);
    for(let k=0;k<cap;k++) p8[k]=par[k];
    str.push({ par:p8, cap, norm:clp((L-6)/90,0,1), mir:(gi&1)?-1:1,
               fan:(fr(gi*2+3)-0.5)*0.95, ph:fr(gi*3+5)*6.283, jit:(fr(gi*5+7)-0.5)*0.14 });
  }
  S.str=str;
}
const str=S.str;

// ---- per-frame dynamics (all rhythm from K, audio ON TOP) ----
const flow  = K.t*(0.55+P.speed*0.5);
const glint = K.t*(0.11+P.speed*0.08);
const swayU = u*(0.018+P.sway*0.05);
const gsx = Math.sin(K.t*0.11)*swayU + Math.sin(K.t*0.041+1.3)*swayU*0.6 + A.lowmid*u*0.02;
const gsy = Math.cos(K.t*0.083)*swayU*0.5 + Math.sin(K.t*0.027)*swayU*0.35;
const gsr = 0.035*Math.sin(K.t*0.067) + 0.02*Math.sin(K.t*0.019+0.7);
const cosR=Math.cos(gsr), sinR=Math.sin(gsr);
const segLen = u*0.011*clp(P.scale,0.4,2.4);
const cr = clp(P.curl,0.05,1.05)*0.5;
const evenA=cr*0.55, oddA=cr;
const baseAng=Math.PI/2;
const N = Math.round(clp(28 + P.density*175,10,200));
const expo = 0.55 + P.energy*0.85 + intn*0.3 + A.rms*0.6;
const ramp = n => { n=clp(n,0,1); return n<0.5 ? cfg.stops[0]+(cfg.stops[1]-cfg.stops[0])*(n/0.5) : cfg.stops[1]+(cfg.stops[2]-cfg.stops[1])*((n-0.5)/0.5); };
const hShift=(P.hue-275)*0.6;

// ---- draw ground (fills frame; slow parallax drift on K.t) ----
const pdx=Math.sin(K.t*0.05)*u*0.012, pdy=Math.cos(K.t*0.037)*u*0.010;
push();
if (aA<1) tint(0,0,100,aA*100);
image(S.gb, pdx-u*0.02, pdy-u*0.02, width+u*0.04, height+u*0.04);
noTint();
pop();

// ---- draw the braided delta ----
push();
blendMode(cfg.add?ADD:BLEND);
noFill(); strokeCap(ROUND); strokeJoin(ROUND);
const glintDots=[];
for (let s=0;s<N;s++){
  const S1=str[s]; const cap=S1.cap; if(cap<3) continue;
  const norm=S1.norm, mir=S1.mir, jf=1+S1.jit;
  let ang=baseAng+S1.fan, lx=0, ly=0;
  const gi=Math.floor((((glint+S1.ph)%1+1)%1)*(cap-1));
  let gx=rootX, gy=rootY;
  const xs=new Array(cap+1), ys=new Array(cap+1);
  xs[0]=rootX+gsx; ys[0]=rootY+gsy;
  for (let k=0;k<cap;k++){
    ang += (S1.par[k]? -oddA:evenA)*jf;
    lx += Math.cos(ang)*segLen; ly += Math.sin(ang)*segLen;
    const off=Math.sin(k*0.42 - flow + S1.ph)*segLen*0.55*(k/cap)*(0.5+cr);
    const pxL=(lx+off)*mir, pyL=ly;
    const rx=pxL*cosR - pyL*sinR, ry=pxL*sinR + pyL*cosR;
    const wx=rootX+rx+gsx, wy=rootY-ry+gsy;
    xs[k+1]=wx; ys[k+1]=wy;
    if(k===gi){ gx=wx; gy=wy; }
  }
  const h=wh(ramp(norm)+hShift+sec*4);
  const sb=clp(cfg.coreBri*0.6 + norm*38, 12, 100);
  const eA=clp(cfg.coreA*(0.45+P.energy*0.9), 8, 60)*aA;
  const gA=clp(cfg.glowA*(0.45+P.energy*0.9), 4, 34)*aA;
  // glow underlay (fat, translucent)
  if(cfg.add){ stroke(h,cfg.sat-20,sb,gA); strokeWeight((2.4+norm*2.6)*(0.6+P.scale*0.4));
    beginShape(); for(let q=0;q<=cap;q++) vertex(xs[q],ys[q]); endShape(); }
  // core line
  stroke(h,cfg.sat,sb,eA); strokeWeight((0.7+(1-norm)*0.8)*(0.6+P.scale*0.4)*(cfg.add?1:1.3));
  beginShape(); for(let q=0;q<=cap;q++) vertex(xs[q],ys[q]); endShape();
  if(cfg.add && s<170) glintDots.push([gx,gy,h,norm]);
}
blendMode(BLEND);
pop();

// ---- streaming current: bright glints flowing along strands (continuous motion, silence-safe) ----
if(cfg.add){
  push(); blendMode(ADD); noStroke();
  const tw=A.treble*u*0.012;
  for(let i=0;i<glintDots.length;i++){ const g=glintDots[i];
    const pulse=0.5+0.5*Math.sin(K.t*2.3+i*0.6);
    const sz=(u*(0.004+0.007*pulse)*(0.6+P.energy)+tw)*(0.7+g[3]);
    fill(wh(cfg.glintH+(g[3]-0.5)*40),56,100,(10+pulse*22)*(0.45+P.energy)*aA + A.rms*30*aA);
    circle(g[0],g[1],sz);
  }
  // delta mouth bloom — breathes on beat + bass, anchors the frame bright
  const gp=clp(0.55+0.35*Math.sin(K.t*1.1)+K.pulse*0.4+A.bass*0.6,0,1.7);
  fill(wh(cfg.glintH),46,100,14*(0.5+P.energy)*gp*aA);
  circle(rootX+gsx,rootY+gsy,u*0.13*(0.7+0.35*gp));
  fill(wh(cfg.glintH+20),36,100,8*(0.5+P.energy)*gp*aA);
  circle(rootX+gsx,rootY+gsy,u*0.26*(0.6+0.3*gp));
  blendMode(BLEND); pop();
}
blendMode(BLEND);
